signature:
type AtlasLanes = {
  /** The colour atlas. */
  color: LaneCounts
  /** The data atlas. */
  data: LaneCounts
}

type CacheSession = {
  /** Called with a page's url as the cache evicts it. */
  evicted?(url: string): void
  /** Called when an eviction over budget found nothing it could take. */
  blocked?(): void
}

type CanvasPoint = {
  /** CSS pixels from the canvas's left edge. */
  x: number
  /** CSS pixels from the canvas's top edge. */
  y: number
}

type CaptureSize = {
  /** Width of the image, in pixels. */
  width: number
  /** Height of the image, in pixels. */
  height: number
}

type CellRows = {
  /** How many nodes the cell holds. */
  nodes: number
  /** Per node, its parent's rank (`-1`: the scene root), then its mesh's. */
  ranks: Int32Array
  /** Per node, its local matrix. */
  locals: Float64Array
}

type CreatedMaterial = Omit<SceneMaterialPatch, 'tiling'> & {
  /** Page label for the new material. */
  name?: string
  /** Caller-owned bitmap, decoded without premultiplication or colour conversion. Keep open until drop. */
  map?: ImageBitmap
}

type DagReport = { warnings?: DagWarning[] } & (
  { stalls?: undefined } | ({ stalls: DagStall[] } & DagStallSummary)
)

type DrawRanks = {
  /** Its mesh rank in the manifest. */
  meshes?: number
  /** Its primitive rank inside that mesh. */
  primitives?: number
  /** The rows that place it, one root each. */
  placements?: PlacementRows
}

type EulerLike = XYZLike & {
  /** The order the three turns apply in, such as `'XYZ'`. */
  order: string
}

type EvictionOrder = {
  /** How many keys the order lists. */
  readonly count: number
  /** The key at rank `at`, the first victim at 0. */
  keyAt(at: number): string
}

type GpuPassBlockTotals = {
  /** Time to find what is visible. */
  visibilityMs: number | null
  /** Time to shade materials. */
  materialsMs: number | null
  /** Everything else. */
  otherMs: number | null
}

type HostBox = {
  /** The lowest corner. */ readonly min: HostPoint
  /** The highest corner. */ readonly max: HostPoint
}

type HostColour = {
  /** Red, linear. */ r: number
  /** Green, linear. */ g: number
  /** Blue, linear. */ b: number
}

type HostDisposable = {
  /** Frees it. */
  dispose(): void
}

type HostNodeMatrix = {
  /** The sixteen numbers, by index. */
  readonly elements: { [index: number]: number; readonly length: number }
}

type HostPoint = {
  /** Left to right. */ readonly x: number
  /** Bottom to top. */ readonly y: number
  /** Back to front. */ readonly z: number
}

type HostScene = {
  /** What fills the image behind. */ readonly background: unknown
  /** The nodes at its top. */ readonly children: readonly object[]
  /** Visits itself, then the subtree. */ traverse(visit: (node: object) => void): void
}

type HostVector = {
  /** Left to right. */
  x: number
  /** Bottom to top. */
  y: number
  /** Back to front. */
  z: number
  /** Writes the three numbers. */
  set(x: number, y: number, z: number): unknown
}

type MatrixElements = {
  /** The sixteen numbers, column by column. */
  readonly elements: ArrayLike<number>
}

type MemoryBudgets = {
  /** Bytes for geometry pages. */
  geometryPoolBytes?: number
  /** Bytes for texture tiles. */
  texturePoolBytes?: number
}

type PageHome = {
  /** Its rank in the catalogue's order. */
  rank: number
  /** Its first byte in the pool. */
  offset: number
  /** Its width, in bytes. */
  bytes: number
}

type PageHomes = {
  /** Each page's home, by key. */
  homes: ReadonlyMap<string, PageHome>
  /** The bytes every home takes together. */
  bytes: number
}

type PageIntegrationPlan = {
  /** Where each cluster goes in the pack. */
  slices: Int32Array
  /** How many clusters. */
  count: number
  /** The page ranks it moves. */
  pages: Int32Array
  /** How many pages. */
  pageCount: number
}

type PhysicsPart = PhysicsPrimitive & {
  /** @defaultValue [0, 0, 0] */ position?: readonly [number, number, number]
  /** A unit quaternion `[x, y, z, w]`. @defaultValue [0, 0, 0, 1] */
  quaternion?: readonly [number, number, number, number]
}

type PixelImage = {
  /** The pixel values, row after row. */
  data: ArrayBufferView
  /** Pixels in one row. */
  width: number
  /** Rows in one layer. */
  height: number
  /** Layers, for a stack of images. */
  depth?: number
}

type PointOfInterest = {
  /** The view's short name, unique in its scene. */
  id: string
  /** The words a page shows for the view. */
  label: string
  /** Where the camera stands and what it looks at. */
  pose: CameraPose
}

type PosedWorld = {
  /** The camera's field of view and near and far distances. */
  camera: { fov: number; near: number; far: number }
}

type PrimitiveDagWarning = DagWarning & {
  /** Its rank in the manifest. */
  index: number
  /** Its mesh's number. */
  mesh: number
  /** Its number in the mesh. */
  primitive: number
}

type RangeAsk = {
  /** Counts the bytes that arrive. */
  meter?: ByteMeter
  /** The most requests `checked` makes for the range. */
  attempts?: number
  /** Lets its asker go: the read stops once none waits on it. */
  signal?: AbortSignal
}

type SceneMaterialPatch = Partial<
  Pick<
    SceneMaterial,
    'baseColor' | 'opacity' | 'metalness' | 'roughness' | 'emissive' | 'alphaMode' | 'alphaCutoff'
  > & {
    /** Map repetitions across and up. */
    tiling: readonly [number, number]
  }
>

type SceneState = {
  /** The transform tree. */
  tree: TransformTree
  /** Nodes by name. */
  ids: Map<string, SceneNode>
  /** The next free name number. */
  nextId: number
  /** The scene root. */
  root?: SceneRoot
}

type SlimClusterManifest = Omit<ClusterManifest, 'primitives'> & {
  /** The binary file. */
  binary: ManifestBinaryDescriptor
  /** Its primitives. */
  primitives: SlimPrimitive[]
}

type SlimPrimitive = Omit<Primitive, 'pages' | 'culling' | 'structure' | 'streams'> & {
  /** Where to find its lists. */
  binary: SlimPrimitiveBinary
}

type TablePage = {
  /** Its file, relative to the tables. */
  url: string
  /** Its size in bytes. */
  bytes: number
  /** Its SHA-256 fingerprint, in hexadecimal. */
  sha256: string
}

type TableSlot = {
  /** The page the slot names. */
  page: TablePage
  /** Its box at the declared poses: the minimum corner, then the maximum. */
  bounds: readonly number[]
  /** The core ranks listed beside it. */
  parents: readonly number[]
}

type TextureLevelReader = ((request: TextureLevelRequest) => Promise<TextureLevel>) & {
  readonly store: TextureLevelStore
  /** The cook the reader was made for: its levels are held in `store` under it. */
  readonly key: string
}

type TextureLevelRequest = TextureLevelAddress & {
  /** The tile's record in the level file, by its first byte and its length; absent, the level
   *  is read whole. */
  range?: { offset: number; bytes: number }
}

type TransformSnap = {
  /** World units a move is rounded to, along each axis. */
  translate?: number
  /** Radians a turn is rounded to. */
  rotate?: number
  /** The step a scale factor is rounded to. */
  scale?: number
}

type WorldFrameMetrics = FrameMetrics & {
  /** Clusters the occlusion test found hidden this frame; `null` where the path does not count them. */
  hizCulled: number | null
}

type WorldPageSource = PageSource & {
  /** The address every page is read against. */
  readonly baseUrl: string
}

type WorldRootsPage = {
  /** Its geometry page's bytes (docs/FORMAT.md, Geometry pages). */
  bytes: Uint8Array
}

type XYLike = {
  /** The first coordinate. */
  x: number
  /** The second coordinate. */
  y: number
}

type XYZLike = {
  /** Left to right. */
  x: number
  /** Bottom to top. */
  y: number
  /** Back to front. */
  z: number
}

type XYZSink = XYZLike & {
  /** Writes the three numbers. */
  set(x: number, y: number, z: number): unknown
}

type XYZWLike = {
  /** The first number. */
  x: number
  /** The second number. */
  y: number
  /** The third number. */
  z: number
  /** The fourth number. */
  w: number
}

type XYZWSink = XYZWLike & {
  /** Writes the four numbers. */
  set(x: number, y: number, z: number, w: number): unknown
}
